import { ImageAnalysisResult } from '@/types';
import * as exifr from 'exifr';
import { cleanText } from '@/lib/text-utils';
import { detectLanguage } from '@/lib/language';

const AI_MARKERS = [
  'midjourney',
  'dall-e',
  'dalle',
  'stable diffusion',
  'comfyui',
  'automatic1111',
  'c2pa',
  'firefly',
  'imagen',
  'flux',
  'bing image creator',
  'gpt-4o',
  'grok',
  'sora',
  'ai generated',
  'generated by ai',
];

const EDITING_SOFTWARE_MARKERS = ['photoshop', 'gimp', 'canva', 'lightroom', 'affinity', 'snapseed', 'picsart'];

export class ImageAnalyzer {
  /**
   * Performs OCR text extraction using Tesseract.js.
   */
  async extractTextOcr(buffer: Buffer): Promise<{ text: string; confidence: number }> {
    try {
      const { createWorker } = await import('tesseract.js');
      const worker = await createWorker(['ara', 'eng']);
      const ret = await worker.recognize(buffer);
      const text = cleanText(ret.data.text || '');
      const confidence = Math.round(ret.data.confidence || 0);
      await worker.terminate();
      return { text, confidence };
    } catch (err: any) {
      console.warn('OCR processing skipped or encountered warning:', err.message);
      return { text: '', confidence: 0 };
    }
  }

  /**
   * Scans raw metadata text regions (e.g. PNG tEXt/iTXt/XMP chunks) for AI generation markers.
   */
  private scanRawAiMarkers(buffer: Buffer): string | null {
    const headStr = buffer.subarray(0, Math.min(buffer.length, 65536)).toString('latin1').toLowerCase();
    const tailStr =
      buffer.length > 65536 ? buffer.subarray(Math.max(0, buffer.length - 16384)).toString('latin1').toLowerCase() : '';
    const combined = `${headStr} ${tailStr}`;

    for (const marker of AI_MARKERS) {
      if (combined.includes(marker)) {
        return marker;
      }
    }
    return null;
  }

  /**
   * Analyzes an image buffer for EXIF/XMP metadata, PNG chunks, OCR text, and manipulation signals.
   */
  async analyze(buffer: Buffer, mimeType = 'image/jpeg'): Promise<ImageAnalysisResult> {
    let exifData: Record<string, any> = {};
    let hasExif = false;
    const manipulationIndicators: string[] = [];
    let aiMarkerDetected = false;

    // 1. Extract EXIF / XMP / IPTC Metadata using exifr
    try {
      const parsed = await exifr.parse(buffer, {
        tiff: true,
        xmp: true,
        icc: true,
        iptc: true,
        jfif: true,
      });

      if (parsed) {
        hasExif = true;
        exifData = {
          Make: parsed.Make,
          Model: parsed.Model,
          DateTimeOriginal: parsed.DateTimeOriginal ? new Date(parsed.DateTimeOriginal).toISOString() : undefined,
          Software: parsed.Software,
          ModifyDate: parsed.ModifyDate ? new Date(parsed.ModifyDate).toISOString() : undefined,
          ImageWidth: parsed.ImageWidth || parsed.ExifImageWidth,
          ImageHeight: parsed.ImageHeight || parsed.ExifImageHeight,
          GPSLatitude: parsed.latitude,
          GPSLongitude: parsed.longitude,
        };

        const software = String(parsed.Software || parsed.CreatorTool || '').toLowerCase();
        if (EDITING_SOFTWARE_MARKERS.some((m) => software.includes(m))) {
          manipulationIndicators.push(`تم حفظ أو تعديل الصورة باستخدام برنامج تحرير رقمي: ${parsed.Software || parsed.CreatorTool}`);
        }
        if (AI_MARKERS.some((m) => software.includes(m))) {
          aiMarkerDetected = true;
          manipulationIndicators.push(
            `بيانات البرمجيات الوصفية تحتوي على علامة محرك توليد ذكاء اصطناعي: ${parsed.Software || parsed.CreatorTool}`
          );
        }
      }
    } catch {
      // Image has no EXIF or unparseable
    }

    // Also scan PNG chunks / XMP strings for embedded AI generator watermarks (e.g. Stable Diffusion, Midjourney, C2PA)
    if (!aiMarkerDetected) {
      const rawMarker = this.scanRawAiMarkers(buffer);
      if (rawMarker) {
        aiMarkerDetected = true;
        manipulationIndicators.push(`رصد توقيع رقمي لمحرك توليد بالذكاء الاصطناعي داخل بنية الملف (${rawMarker}).`);
      }
    }

    // 2. Perform OCR Text Extraction
    const ocrResult = await this.extractTextOcr(buffer);
    const ocrText = ocrResult.text;
    const ocrConfidence = ocrResult.confidence;
    const detectedLang = ocrText ? detectLanguage(ocrText).code : 'ar';

    // 3. Compression / Metadata Integrity Indicator
    let elaScore = 15;
    if (!hasExif && (mimeType.includes('jpeg') || mimeType.includes('webp'))) {
      elaScore += 20;
      manipulationIndicators.push('البيانات الوصفية (EXIF) مفقودة أو تم تجريدها، وهو نمط شائع عند إعادة النشر عبر منصات التواصل.');
    }
    if (manipulationIndicators.some((m) => m.includes('تحرير رقمي'))) {
      elaScore += 30;
    }

    // 4. AI Generation Likelihood Score (conservative unless explicit metadata/C2PA signature is found)
    let aiScore = 10;
    if (aiMarkerDetected) {
      aiScore = 88;
    } else if (elaScore >= 45) {
      aiScore = 25;
    }

    return {
      ocrText,
      ocrConfidence,
      language: detectedLang,
      exif: exifData,
      hasExif,
      elaScore: Math.min(100, Math.max(0, elaScore)),
      aiProbabilityScore: Math.min(100, Math.max(0, aiScore)),
      aiProbabilityDisclaimer:
        'مؤشر احتمالي يعتمد على فحص البيانات الوصفية وتوقيعات البرمجيات (EXIF/XMP/C2PA)، ولا يُعد وحده دليلاً قاطعاً دون تحقق بصري.',
      manipulationIndicators,
    };
  }
}

export const globalImageAnalyzer = new ImageAnalyzer();
